<script setup lang="ts">import {Link,useForm} from '@inertiajs/vue3';import type {SitePage} from '@/types';const props=defineProps<{page?:SitePage}>();const form=useForm({slug:props.page?.slug??'',title:props.page?.title??'',content:props.page?.content??'',meta_title:props.page?.meta_title??'',meta_description:props.page?.meta_description??'',is_published:props.page?.is_published??false});const submit=()=>props.page?form.put(route('admin.content.update',props.page.id)):form.post(route('admin.content.store'));</script>
<template><form class="panel form-panel" @submit.prevent="submit"><div class="form-grid"><div class="field"><label for="title">Título</label><input id="title" v-model="form.title" required maxlength="255"><span class="field-error">{{ form.errors.title }}</span></div><div class="field"><label for="slug">Slug</label><input id="slug" v-model="form.slug" required maxlength="255" pattern="[A-Za-z0-9_-]+"><span class="field-error">{{ form.errors.slug }}</span></div><div class="field field--wide"><label for="content">Contenido</label><textarea id="content" v-model="form.content" maxlength="100000" rows="16"></textarea><span class="field-error">{{ form.errors.content }}</span></div><div class="field"><label for="meta-title">Título SEO</label><input id="meta-title" v-model="form.meta_title" maxlength="255"><span class="field-error">{{ form.errors.meta_title }}</span></div><div class="field"><label for="meta-description">Meta descripción</label><textarea id="meta-description" v-model="form.meta_description" maxlength="1000" rows="4"></textarea><span class="field-error">{{ form.errors.meta_description }}</span></div></div><label class="check-row"><input v-model="form.is_published" type="checkbox"> Página publicada</label><div class="form-actions"><Link class="button button--outline-small" :href="route('admin.content.index')">Cancelar</Link><button class="button button--admin" :disabled="form.processing">{{ form.processing?'Guardando...':'Guardar página' }}</button></div></form></template>
